'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Tests whether a one-dimensional double-precision floating-point ndarray contains at least `k` truthy elements.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the minimum number of truthy elements.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {boolean} boolean indicating whether the input ndarray contains at least `k` truthy elements
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Float64Vector( [ 0.0, 0.0, 1.0, 2.0 ] );
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'int32'
* });
*
* var v = dsome( [ x, k ] );
* // returns true
*/
function dsome( arrays ) {
	var x = arrays[ 0 ];
	var k = arrays[ 1 ];
	return addon( getData( x ), serialize( x ), getData( k ), serialize( k ) );
}


// EXPORTS //

module.exports = dsome;
